class Solution {
public:
    int minimumCardPickup(vector<int>& cards) {
        unordered_map<int, int> lastSeen;
        int ans = INT_MAX;
        for (int i = 0; i < (int)cards.size(); i++) {
            int val = cards[i];
            if (lastSeen.count(val)) {
                int span = i - lastSeen[val] + 1;
                if (span < ans) {
                    ans = span;
                }
            }
            lastSeen[val] = i;
        }
        return (ans == INT_MAX) ? -1 : ans;
    }
};
